<?php

namespace Database\Seeders;

use App\Models\PlantillaProducto;
use App\Models\Seccion;
use App\Services\CatalogoCotizador;
use Illuminate\Database\Seeder;

class PlantillaEjemploSeeder extends Seeder
{
    public function run()
    {
        app(CatalogoCotizador::class)->asegurar();   // crea los bloques nuevos si faltan
        $bloques = Seccion::pluck('id', 'nombre');
        $faltan  = [];

        foreach ($this->plantillas() as $p) {
            $plantilla = PlantillaProducto::updateOrCreate(
                ['producto' => $p['producto'], 'tipo_operacion' => $p['tipo'], 'sucursal' => $p['sucursal']],
                ['descripcion' => $p['descripcion'], 'activo' => true]
            );
            $plantilla->conceptos()->delete();

            foreach ($p['conceptos'] as $orden => $c) {
                list($bloque, $codigo, $descripcion, $usd, $mxn, $alCosto, $doc, $nota) = $c;
                if (!isset($bloques[$bloque])) {
                    $faltan[$bloque] = true;
                    continue;
                }
                $plantilla->conceptos()->create([
                    'seccion_id'      => $bloques[$bloque],
                    'codigo'          => $codigo,
                    'descripcion'     => $descripcion,
                    'cantidad'        => 1,
                    'precio_usd'      => $usd,
                    'precio_mxn'      => $mxn,
                    'al_costo'        => $alCosto,
                    'descripcion_doc' => $doc,
                    'nota'            => $nota,
                    'orden'           => $orden,
                ]);
            }

            $this->command->info(sprintf('  %-26s %-12s %3d conceptos', $p['producto'], $p['tipo'], $plantilla->conceptos()->count()));
        }

        if ($faltan) {
            $this->command->warn('Bloques que no existen (conceptos omitidos): ' . implode(', ', array_keys($faltan)));
        }
    }

